const task = await folder.file('task.json').readJson();
type Draft = { reviewId: string; selectedId: "none" | "CCR-2A" | "CCR-2B" | "CCR-2C" | "CCR-2D"; eligibleIds: string; priorityScore: string; decision: "approve" | "hold" };
type Progress = { pass: number; notes: Neuralese<string> };
type CandidateSpec = { candidateId: string; priority_path: string; eligibility_path: string };
type ScoreFact = { candidateId: string; score: number };
type EligibilityFact = { candidateId: string; eligible: boolean; evidence: string };
const seed: Neuralese<(initialDraft: unknown) => Promise<Neuralese<string>>> = nl.with<Neuralese<string>>({})`Write a short readable starting note saying the supplied draft is a placeholder and no evidence has been reviewed. Return Neuralese<string> prose only.`;
const initialNotes = await seed(task.initialDraft);
const revise = async (progress: Progress): Promise<Progress> => {
  if (progress.pass === 0) {
    const source = folder.file(task.passes[0].evidence_path);
    const readReview: Neuralese<(source: FileHandle, priorNotes: Neuralese<string>) => Promise<Neuralese<string>>> = nl.with<Neuralese<string>>({})`Read only the supplied review-notice FileHandle and priorNotes. Extract the review ID, deadline, requested action, and all decision-rule facts from this file. Return a complete updated readable note as Neuralese<string>. Do not infer any later evidence.`;
    const notes = await readReview(source, progress.notes);
    return { pass: progress.pass + 1, notes };
  }
  if (progress.pass === 1) {
    const readScore: Neuralese<(source: FileHandle, candidateId: string, priorNotes: Neuralese<string>) => Promise<ScoreFact>> = nl.with<ScoreFact>({})`Read the supplied single-candidate priority FileHandle. Use priorNotes only for the review identifier and priority units if needed. Return only its candidateId and numeric priority score as a typed object. Do not infer eligibility or inspect another candidate.`;
    const scoreFacts = await Promise.all(task.candidates.map(async (candidate: CandidateSpec) => {
      const source = folder.file(candidate.priority_path);
      return await readScore(source, candidate.candidateId, progress.notes);
    }));
    const compareScores: Neuralese<(priorNotes: Neuralese<string>, candidates: ScoreFact[]) => Promise<Neuralese<string>>> = nl.with<Neuralese<string>>({})`Combine priorNotes with these four scored candidate records. Preserve every candidate and score with the exact units supplied by the task. State which score is highest, and mark the result provisional because eligibility is not yet known. Return the complete updated readable evidence note as Neuralese<string>; do not decide eligibility or action.`;
    const notes = await compareScores(progress.notes, scoreFacts);
    return { pass: progress.pass + 1, notes };
  }
  if (progress.pass === 2) {
    const readEligibility: Neuralese<(source: FileHandle, candidateId: string, priorNotes: Neuralese<string>) => Promise<EligibilityFact>> = nl.with<EligibilityFact>({})`Read the supplied single-candidate eligibility FileHandle. Apply every stated eligibility requirement from priorNotes to this candidate's exact evidence. Return only candidateId, eligible true/false, and the exact evidence phrase as a typed object. Do not rank or decide the action.`;
    const eligibilityFacts = await Promise.all(task.candidates.map(async (candidate: CandidateSpec) => {
      const source = folder.file(candidate.eligibility_path);
      return await readEligibility(source, candidate.candidateId, progress.notes);
    }));
    const reconcileCandidates: Neuralese<(priorNotes: Neuralese<string>, candidates: EligibilityFact[]) => Promise<Neuralese<string>>> = nl.with<Neuralese<string>>({})`Combine priorNotes with these four candidate eligibility records. Preserve each exact eligibility finding. Rank only candidates marked eligible by descending observed priority score, breaking ties by ascending complete candidate ID; report the selected candidate and eligible ordering, or none when the set is empty. The signature prerequisite remains unresolved. Return the complete updated readable evidence note as Neuralese<string>, not a Draft.`;
    const notes = await reconcileCandidates(progress.notes, eligibilityFacts);
    return { pass: progress.pass + 1, notes };
  }
  const source = folder.file(task.passes[3].evidence_path);
  const readAuthorization: Neuralese<(source: FileHandle, priorNotes: Neuralese<string>) => Promise<Neuralese<string>>> = nl.with<Neuralese<string>>({})`Read only the supplied authorization FileHandle and priorNotes. Record whether the authorized reviewer signed this exact review by its deadline. Return the complete updated readable note as Neuralese<string>. Do not change prior candidate facts or decide beyond the stated decision rule.`;
  const notes = await readAuthorization(source, progress.notes);
  return { pass: progress.pass + 1, notes };
};
const completed = await iterateOn(revise, { pass: 0, notes: initialNotes })
 .withLimit({ maxSteps: task.passes.length }).until(state => state.pass === task.passes.length);
const interpret: Neuralese<(notes: Neuralese<string>) => Promise<Draft>> = nl.with<Draft>({
 taskInstruction: task.instruction, outputContract: JSON.stringify(task.output_contract),
 decisionRule: task.output_contract.decision_rule, outputPath: task.output_path
})`Read the accumulated evidence note. Apply exactly the task's decision rule to the supported facts and return the complete final Draft with each field in its declared format. Do not invent facts or add prerequisites. For eligibleIds, preserve descending priority and ascending full-ID tie order; use none when no item is eligible. Approve only if the winning item is eligible and the authorized reviewer signed this review by its deadline. Return the exact typed Draft without explanation.`;
const finalDraft = await interpret(completed.notes);
await folder.file(task.output_path).writeText(JSON.stringify(finalDraft));
const saved = await folder.file(task.output_path).readJson();
if (JSON.stringify(saved) !== JSON.stringify(finalDraft)) throw Error('saved draft differs');
return finalDraft;

